// ─── File: ReportingDemo.java ───
// Runnable demo: simulates NATURAL vs explicit join, CROSS join, and ROLLUP in memory.
package com.bank.reporting;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ReportingDemo {
    private static final Logger log = Logger.getLogger(ReportingDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ReportingRepository repo = new ReportingRepository();
        ReportingService service = new ReportingService(repo);

        log.info("=== SAFE explicit join (replaces dangerous NATURAL JOIN) ===");
        service.spendPerAccount().forEach((id, amt) ->
            log.info(() -> "Account " + id + " spent Rs." + amt));

        log.info("=== CROSS JOIN campaign matrix ===");
        service.campaignMatrix().forEach(line -> log.info(line));

        log.info("=== ROLLUP spending report (region, branch, grand total) ===");
        service.rollupReport().forEach(line -> log.info(line));
    }
}

