class ReportingRepository {
    List<Account> accounts() {
        return List.of(
            new Account("SAV2001", "Rajesh Kumar", "North", "Delhi"),
            new Account("CUR3001", "Priya Sharma", "West",  "Mumbai"));
    }
    List<String> offers() { return List.of("PlatinumCard", "TravelCard", "FuelCard"); }
    // (accountId, amount) spend rows
    List<SpendRow> spends() {
        return List.of(
            new SpendRow("North", "Delhi",  new BigDecimal("40000")),
            new SpendRow("North", "Delhi",  new BigDecimal("10000")),
            new SpendRow("West",  "Mumbai", new BigDecimal("25000")));
    }
}

