class ReportingService {
    private static final Logger log = Logger.getLogger(ReportingService.class.getName());
    private final ReportingRepository repo;
    ReportingService(ReportingRepository repo) { this.repo = repo; }

    // Explicit join equivalent: one row per account with total spend.
    Map<String, BigDecimal> spendPerAccount() {
        Map<String, BigDecimal> totals = new LinkedHashMap<>();
        for (Account a : repo.accounts()) {
            BigDecimal sum = repo.spends().stream()
                .filter(s -> s.region.equals(a.region) && s.branch.equals(a.branch))
                .map(s -> s.amount).reduce(BigDecimal.ZERO, BigDecimal::add);
            totals.put(a.accountId, sum);
        }
        return totals;
    }

    // CROSS JOIN: every account paired with every offer.
    List<String> campaignMatrix() {
        List<String> rows = new ArrayList<>();
        for (Account a : repo.accounts())
            for (String offer : repo.offers())
                rows.add(a.holderName + " -> " + offer);
        return rows;
    }

    // ROLLUP: detail rows + per-region subtotal + grand total.
    List<String> rollupReport() {
        List<String> out = new ArrayList<>();
        Map<String, BigDecimal> byRegion = new LinkedHashMap<>();
        BigDecimal grand = BigDecimal.ZERO;
        for (SpendRow s : repo.spends()) {
            out.add("DETAIL  " + s.region + "/" + s.branch + " = Rs." + s.amount);
            byRegion.merge(s.region, s.amount, BigDecimal::add);
            grand = grand.add(s.amount);
        }
        byRegion.forEach((r, amt) -> out.add("SUBTOTAL " + r + " (branch=NULL) = Rs." + amt));
        out.add("GRANDTOTAL (region=NULL, branch=NULL) = Rs." + grand);
        return out;
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
